select TBS067.NFSNUM,dbo.NFSTOTLIQ(0,TBS067.NFSNUM,0,TBS067.SNESER) from TBS0671 (nolock) inner join TBS067 (nolock) on TBS067.SNESER=TBS0671.SNESER and TBS067.NFSNUM=TBS0671.NFSNUM
 where NFSDATEMI between '20161201' and '20161231' and NFSCFOP='5.922' group by TBS067.NFSNUM,TBS067.SNESER,NFSDATEMI order by TBS067.NFSDATEMI desc